  /* Nivel editorial automático (docs/EXPANSION-STRATEGY.md): A oficial, B comunidad, C directorio.
     Un recurso puede forzar su nivel con level: "A" | "B" | "C". */
  const OFFICIAL_HOSTS = /(^|\.)(gob\.es|gencat\.cat|barcelona\.cat|ajuntament\.barcelona\.cat|sitges\.cat|tmb\.cat|atm\.cat|renfe\.com|aerobusbcn\.com|bicing\.barcelona|policia\.es|diba\.cat|ccma\.cat|rtve\.es|sanidad\.gob\.es|sem\.gencat\.cat|112\.gencat\.cat)$/i;
  const levelOf = (item) => {
    if (item.level) return item.level;
    try {
      const host = new URL(item.url).hostname.replace(/^www\./, "");
      return OFFICIAL_HOSTS.test(host) ? "A" : "B";
    } catch { return "C"; }
  };
  resources.forEach((item) => { item.level = levelOf(item); });

  const tools = Object.freeze({
    healthRoutes, healthTopics, soundPresets,
    checklists: checklistTemplates, transport
  });

